class Solution:
    def replaceElements(self, arr: list[int]) -> list[int]:
        n = len(arr)
        best = arr[-1]
        for i in range(n - 2, -1, -1):
            tmp = best
            best = max(best, arr[i])
            arr[i] = tmp

        arr[-1] = -1
        return arr
